#include <cstdio>
using namespace std;

int main() {
    int a[7] = {2, 4, 6, 8, 10, 12, 14};
    int n = 7, x = 14;
    int lo = 0, hi = n - 1;
    int ans = -1;
    while (lo <= hi && ans == -1) {
        int mid = (lo + hi) / 2;
        printf("%d ", a[mid]);
        if (a[mid] == x) {
            ans = mid + 1;
        } else if (a[mid] < x) {
            lo = mid + 1;
        } else {
            hi = mid - 1;
        }
    }
    printf("\n");
    return 0;
}

